const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={road:mat(0x444b4c),side:mat(0xc9c6b7),cream:mat(0xe6d4b8),window:mat(0x6d9ba4,.28,.1),darkglass:mat(0x3f626b,.25,.12),brick:mat(0xc87652),sage:mat(0x8eaa8d),yellow:mat(0xd8b45d),blue:mat(0x7797a0),roof:mat(0x564f49),green:mat(0x426b4c),leaf:mat(0x5e8751),pot:mat(0xb66e50),white:mat(0xf0e9d8),black:mat(0x273234),orange:mat(0xe98431),orangeLight:mat(0xffad52),pink:mat(0xeb958d),skin:mat(0xe9b89a),uniform:mat(0x344c6b),dog:mat(0x685542)};
function box(parent,x,y,z,sx,sy,sz,material,shadow=true){const o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);o.position.set(x,y,z);o.castShadow=shadow;o.receiveShadow=true;parent.add(o);return o}
