// pots and shrubs flanking each storefront
for(let side of [-1,1]){const px=x+side*(w*.43+.65),pz=z+d/2+.8;const pot=cylinder(world,px,.42,pz,.36,.48,.8,mats.pot);cylinder(world,px,.85,pz,.42,.42,.16,mat(0x443b34));sphere(world,px,.95,pz,.34,.3,.34,mats.leaf);destructibles.push({mesh:pot,hp:1,max:1,kind:'flowerpot',x:px,z:pz,score:12})}
}
let bi=0;for(let x=-45;x<=45;x+=15)for(let z=-45;z<=45;z+=15){if(Math.abs(x)<20&&Math.abs(z)<20)continue;addBuilding(x+(Math.random()-.5)*2,z+(Math.random()-.5)*2,++bi)}
