// Food bowl at the front door
cylinder(home,0,.25,2.8,.56,.64,.32,mat(0x4f7280));for(let i=0;i<7;i++)sphere(home,(Math.random()-.5)*.55,.43,2.8+(Math.random()-.5)*.45,.12,.09,.11,mat(0x9c6a37));

