const keys={};let yaw=0,score=0,crime=0,wantedLevel=0,lives=3,energy=100,started=false,attackCD=0,meowCD=0,arrestCD=0,chaos=0,gameTime=0,toastTimer=0,shake=0;
const down=e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!started)return;if(e.code==='KeyE')swat();if(e.code==='KeyQ')meow();if(e.code==='Space'&&cat.position.y<.03){cat.userData.vy=6.5}};
