function notify(text){const el=$('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.3}
function refreshHUD(){$('#score').textContent=String(score).padStart(4,'0');$('#wanted').textContent='★'.repeat(wantedLevel)+'☆'.repeat(5-wantedLevel);$('#lives').innerHTML=Array.from({length:3},(_,i)=>i<lives?'♥':'♡').join(' ');$('#progress').style.width=Math.min(100,chaos%100)+'%';if(chaos<100){$('#agenda').textContent=chaos<30?'Cause a little chaos.':chaos<70?'The neighborhood noticed.':'Local legend in the making.';$('#agendaSub').textContent=chaos<30?'The whole city is your scratching post.':'Keep exploring — there is no wrong way to cat.'}else{$('#agenda').textContent='The city is your playground!';$('#agendaSub').textContent='Go on, make another memory.'}}
function raiseCrime(amount=1){crime+=amount;chaos+=amount;wantedLevel=Math.min(5,Math.floor(crime/2)+1);score+=Math.floor(amount*10);refreshHUD();if(wantedLevel>police.length){const a=Math.random()*Math.PI*2,r=25+Math.random()*8;police.push(makeOfficer(cat.position.x+Math.cos(a)*r,cat.position.z+Math.sin(a)*r));notify('Uh oh — the paw patrol is on the way!')} }
function burst(pos,color=0xe6b77a,count=12){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.BoxGeometry(.14,.14,.14),mat(color));m.position.copy(pos);world.add(m);const v=new THREE.Vector3((Math.random()-.5)*7,Math.random()*6,(Math.random()-.5)*7);let t=.7;function step(dt){if(!m.parent)return;t-=dt;m.position.addScaledVector(v,dt);v.y-=10*dt;m.rotation.x+=dt*6;if(t<=0){world.remove(m);return}requestAnimationFrame(()=>step(.016))}step(.016)}}
function swat(){if(attackCD>0)return;attackCD=.55;cat.userData.swing=.5;let best=null,bd=3.1;for(const d of destructibles){if(!d.mesh.parent)continue;const dx=d.x-cat.position.x,dz=d.z-cat.position.z,dist=Math.hypot(dx,dz);const forward=Math.sin(yaw)*dx+Math.cos(yaw)*dz;if(dist<bd&&forward>-.7){bd=dist;best=d}}
let personHit=null;for(const p of people){const dist=p.group.position.distanceTo(cat.position);if(dist<2.1&&!personHit)personHit=p}
if(best){best.hp--;if(best.hp<=0){if(best.kind==='building'){world.remove(best.group);burst(new THREE.Vector3(best.x,3,best.z),0xc7a886,30)}else{if(best.mesh.parent)best.mesh.parent.remove(best.mesh);burst(new THREE.Vector3(best.x,.6,best.z),best.kind==='flowerpot'?0xb76f50:0x5ba38b,13)}score+=best.score;chaos+=Math.max(3,Math.floor(best.score/4));raiseCrime(best.score>20?2:1);notify(best.kind==='building'?'CRUNCH! A whole building came down!':`${best.kind==='flowerpot'?'Flowerpot':'Street prop'}: absolutely obliterated.`);refreshHUD()}else{notify('Scritch, scratch! Keep swatting to break it.');score+=2;}}
else if(personHit){personHit.state='flee';personHit.timer=4;raiseCrime(1);notify('The neighbors are running!');}
else{notify('A mighty paw swipe! (Try a flowerpot or building.)');score+=1;}}
function meow(){if(meowCD>0)return;meowCD=2.1;cat.userData.meow=.7;notify('Mrrrow! Those eyes are impossible to resist.');for(const p of people){const dist=p.group.position.distanceTo(cat.position);if(dist<14){p.state='charm';p.timer=5;p.hearts=1}}}
function arrest(){if(arrestCD>0)return;arrestCD=3.5;lives=Math.max(1,lives-1);wantedLevel=0;crime=0;for(const p of police){world.remove(p.group);world.remove(p.dog)}police.length=0;cat.position.set(-7,0,3.8);energy=100;notify('Busted! A snack and a nap at home, then back to mischief.');refreshHUD()}
$('#play').addEventListener('click',()=>{$('#start').classList.add('hidden');started=true;notify('Welcome home, Marmalade. Go be a cat!')});
function update(dt){gameTime+=dt;attackCD=Math.max(0,attackCD-dt);meowCD=Math.max(0,meowCD-dt);arrestCD=Math.max(0,arrestCD-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}
const forward=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw)),right=new THREE.Vector3(Math.cos(yaw),0,-Math.sin(yaw));let move=new THREE.Vector3();if(keys.KeyW||keys.ArrowUp)move.add(forward);if(keys.KeyS||keys.ArrowDown)move.sub(forward);if(keys.KeyA||keys.ArrowLeft)move.sub(right);if(keys.KeyD||keys.ArrowRight)move.add(right);if(move.lengthSq()>0){move.normalize();const speed=(keys.ShiftLeft||keys.ShiftRight)?9:5.3;cat.position.addScaledVector(move,speed*dt);cat.rotation.y=Math.atan2(move.x,move.z);cat.userData.walk=(cat.userData.walk||0)+dt*speed*1.6;energy=Math.max(0,energy-((speed>7)?dt*3:0))}else energy=Math.min(100,energy+dt*2);
// gentle hops and paw steps
cat.userData.vy=(cat.userData.vy||0)-16*dt;cat.position.y+=cat.userData.vy*dt;if(cat.position.y<0){cat.position.y=0;cat.userData.vy=0}const walk=cat.userData.walk||0;cat.userData.legs.forEach((l,i)=>{l.position.y=.25+Math.sin(walk+(i%2)*Math.PI)*.07;l.rotation.x=Math.sin(walk+(i%2)*Math.PI)*.35});cat.userData.tail.rotation.x=Math.sin(gameTime*4)*.36;cat.userData.tail.rotation.z=Math.sin(gameTime*2.7)*.32;cat.rotation.z=cat.userData.swing?Math.sin(gameTime*38)*.13:0;if(cat.userData.swing)cat.userData.swing=Math.max(0,cat.userData.swing-dt);cat.userData.meow=Math.max(0,(cat.userData.meow||0)-dt);
cat.position.x=THREE.MathUtils.clamp(cat.position.x,-62,62);cat.position.z=THREE.MathUtils.clamp(cat.position.z,-62,62);
// Home: replenish energy and a cozy little purr
if(cat.position.distanceTo(new THREE.Vector3(-7,0,7))<3){energy=Math.min(100,energy+dt*20);if(keys.KeyF){lives=3;crime=0;wantedLevel=0;notify('Fresh kibble. Full whiskers. Full lives.');keys.KeyF=false;refreshHUD()}}
// residents respond to paws and meows, then wander again
for(const p of people){const g=p.group,dx=cat.position.x-g.position.x,dz=cat.position.z-g.position.z,dist=Math.hypot(dx,dz);p.phase+=dt;if(p.state==='flee'){const d=dist||1;g.position.x-=dx/d*dt*4.8;g.position.z-=dz/d*dt*4.8;p.timer-=dt;if(p.timer<=0)p.state='wander'}else if(p.state==='charm'){if(dist>1.8){g.position.x+=dx/(dist||1)*dt*1.5;g.position.z+=dz/(dist||1)*dt*1.5;}p.timer-=dt;if(p.timer<=0)p.state='wander';}else{p.timer-=dt;if(p.timer<0){p.timer=1+Math.random()*3;p.dx=(Math.random()-.5)*1.5;p.dz=(Math.random()-.5)*1.5}g.position.x+=(p.dx||0)*dt;g.position.z+=(p.dz||0)*dt;}g.rotation.y=Math.atan2(dx,dz);g.position.y=Math.abs(Math.sin(p.phase*5))*.035;if(p.state==='flee')g.rotation.y+=Math.PI;}
for(const p of police){const dx=cat.position.x-p.group.position.x,dz=cat.position.z-p.group.position.z,d=Math.hypot(dx,dz)||1;p.group.rotation.y=Math.atan2(dx,dz);p.group.position.x+=dx/d*dt*(2.5+wantedLevel*.35);p.group.position.z+=dz/d*dt*(2.5+wantedLevel*.35);p.dog.position.set(p.group.position.x+Math.sin(gameTime*9)*.6,.02,p.group.position.z+Math.cos(gameTime*9)*.6);p.dog.rotation.y=p.group.rotation.y;if(d<1.6)arrest();}
// Wanted level cools down slowly if you keep a low profile
if(wantedLevel>0&&gameTime%9<dt){crime=Math.max(0,crime-1);wantedLevel=crime?Math.min(5,Math.floor(crime/2)+1):0;refreshHUD()}
// camera tracks cat with damped follow and a slight cinematic tilt
const target=new THREE.Vector3(cat.position.x-Math.sin(yaw)*9,cat.position.y+5.4,cat.position.z-Math.cos(yaw)*9);camera.position.lerp(target,1-Math.exp(-dt*4));camera.lookAt(cat.position.x,cat.position.y+1,cat.position.z);
const nearHome=cat.position.distanceTo(new THREE.Vector3(-7,0,7))<4;$('#hint').textContent=nearHome?'F  ·  refill lives & energy':`Energy ${Math.round(energy)}%`;$('#hint').classList.toggle('show',nearHome||energy<30);
}
function animate(){requestAnimationFrame(animate);const dt=Math.min(.04,clock.getDelta());if(started)update(dt);renderer.render(scene,camera)}const clock=new THREE.Clock();cat.position.set(-7,0,3.8);camera.position.set(-7,7,-8);camera.lookAt(-7,1,3.8);animate();
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
</script></body></html>

